use serde_json::{json,Value};fn main(){let source:Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();let out=source.as_array().unwrap().iter().map(|c|json!({"request":c["request"],"response":ingetrazo_core::ai_protocol::handle(&c["request"],|name,args|json!({"content":[{"type":"text","text":name}],"isError":false,"arguments":args}))})).collect::<Vec<_>>();println!("{}",serde_json::to_string_pretty(&out).unwrap());}
